files.Cargo.toml:
[package]
name = "mongorust-mongodb-struct-dtos-full-caller"
version = "0.1.0"
edition = "2024"

[dependencies]
async-trait = "0.1.92"
chrono = { version = "0.4.45", default-features = false, features = ["clock", "std"] }
rust_decimal = "1.43.0"
mongodb = { version = "3.10.2", default-features = false, features = ["compat-3-3-0", "bson-3", "rustls-tls", "dns-resolver"] }
tokio = { version = "1.54.1", features = ["sync"] }
uuid = { version = "1.29.3", features = ["v4"] }

[dev-dependencies]
tokio = { version = "1.54.1", features = ["macros", "rt-multi-thread", "sync"] }

