            number: bson_values::read(document, "number", bson_values::as_f64)?,
            year: bson_values::read(document, "year", bson_values::as_f64)?,
            customer: bson_values::read(document, "customer", bson_values::as_object_id)?,
            lines: bson_values::read(document, "lines", bson_values::as_list(bson_values::as_nested(OrderLine::from_document)))?,
            notes: bson_values::read(document, "notes", bson_values::as_list(bson_values::as_nested(OrderNote::from_document)))?,
            placed_at: bson_values::read(document, "placedAt", bson_values::as_moment)?,
            loaded_document: Loaded::default(),
        };
        entity.loaded_document = Loaded(Some(entity.to_document()?));
        Ok(entity)
    }

    /// Its document: what is None is left out.
    pub fn to_document(&self) -> Result<Document, Error> {
        let mut document = Document::new();
        bson_values::write(&mut document, "_id", &self.id, bson_values::of_object_id)?;
        bson_values::write(&mut document, "number", &self.number, bson_values::of_f64)?;
        bson_values::write(&mut document, "year", &self.year, bson_values::of_f64)?;
        bson_values::write(&mut document, "customer", &self.customer, bson_values::of_object_id)?;
        bson_values::write(&mut document, "lines", &self.lines, bson_values::of_list(bson_values::of_nested(OrderLine::to_document)))?;
        bson_values::write(&mut document, "notes", &self.notes, bson_values::of_list(bson_values::of_nested(OrderNote::to_document)))?;
        bson_values::write(&mut document, "placedAt", &self.placed_at, bson_values::of_moment)?;
        Ok(document)
    }

    /// Gives an identifier to the documents of its lists that have none: MongoDB numbers only whole documents.
    pub fn identify_items(&mut self) {
        for item in self.lines.iter_mut().flatten() {
            item.id.get_or_insert_with(|| ObjectId::new().to_hex());
        }
        for item in self.notes.iter_mut().flatten() {
            item.id.get_or_insert_with(|| ObjectId::new().to_hex());
        }
    }
}

