/// Keeps orders rows in memory, for tests and for trying the services without a database. Its copies share the rows.
#[derive(Clone, Default)]
pub struct MemoryOrderRepository {
    rows: Arc<Mutex<Vec<Order>>>,
}

impl MemoryOrderRepository {
    /// The rows reads see, by primary key.
    fn visible(&self) -> Vec<Order> {
        let mut rows: Vec<Order> = self.rows.lock().unwrap().iter().cloned().collect();
        rows.sort_by(|a, b| key_of(a).partial_cmp(&key_of(b)).unwrap_or(Ordering::Equal));
        rows
    }

    /// Keeps a row, in place of the one with its key.
    fn store(&self, entity: &Order) {
        let mut rows = self.rows.lock().unwrap();
        rows.retain(|row| key_of(row) != key_of(entity));
        rows.push(entity.clone());
    }
}

/// The key of a row, as a tuple of its key values.
fn key_of(row: &Order) -> (Option<String>,) {
    (row.id.clone(),)
}

