//! The service of the "countries" table.

use crate::dtos::country::{CountryCreate, CountryRead, CountryUpdate};
use crate::entities::country::Country;
use crate::errors::{DomainError, FieldError};
use crate::unit_of_work::UnitOfWork;
use std::sync::Arc;

/// Operations on countries. It never commits: the caller owns the transaction.
pub struct CountryService {
    unit_of_work: Arc<dyn UnitOfWork>,
}

impl CountryService {
    pub fn new(unit_of_work: Arc<dyn UnitOfWork>) -> Self {
        Self { unit_of_work }
    }

    /// Stores a new Country after checking it.
    pub async fn create_country(&self, data: CountryCreate) -> Result<CountryRead, DomainError> {
        let values = Values { document_id: data.document_id.map(Some), id: data.id.map(Some), name: data.name.map(Some) };
        let uow = self.unit_of_work.as_ref();
        check_values(uow, &values, None).await?;
        let mut entity = Country::default();
        apply_values(&mut entity, &values);
        let created = uow.countries().insert(entity).await?;
        Ok(read(created))
    }

    /// The Country with this key; NotFound when there is none.
    pub async fn get_country(&self, document_id: String) -> Result<CountryRead, DomainError> {
        find(self.unit_of_work.as_ref(), document_id).await.map(read)
    }

    /// Every Country, by primary key.
    pub async fn list_countries(&self) -> Result<Vec<CountryRead>, DomainError> {
        self.unit_of_work.countries().list().await.map(|rows| rows.into_iter().map(read).collect())
    }

    /// Changes the given values of a Country.
    pub async fn update_country(&self, document_id: String, changes: CountryUpdate) -> Result<CountryRead, DomainError> {
        let values = given(changes);
        let uow = self.unit_of_work.as_ref();
        let mut current = find(uow, document_id).await?;
        check_values(uow, &values, Some(&current)).await?;
        apply_values(&mut current, &values);
        let updated = uow.countries().update(current).await?;
        Ok(read(updated))
    }

    /// Deletes a Country.
    pub async fn delete_country(&self, document_id: String) -> Result<(), DomainError> {
        let uow = self.unit_of_work.as_ref();
        let current = find(uow, document_id).await?;
        uow.countries().delete(&current).await?;
        Ok(())
    }

    /// The Country with this id, or None.
    pub async fn find_country_by_id(&self, id: f64) -> Result<Option<CountryRead>, DomainError> {
        self.unit_of_work.countries().find_by_id(id).await.map(|row| row.map(read))
    }
}

/// The values a create or an update gives, by field: None when not given, Some(None) when given empty.
#[derive(Default)]
struct Values {
    document_id: Option<Option<String>>,
    id: Option<Option<f64>>,
    name: Option<Option<String>>,
}

/// Checks the values against the rules of the "countries" table, and the rows they point to; ValidationFailed lists every problem.
async fn validate(_uow: &dyn UnitOfWork, values: &Values, current: Option<&Country>) -> Result<(), DomainError> {
    let creating = current.is_none();
    let mut errors = Vec::new();
    match values.document_id.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.document_id.is_some() {
                errors.push(FieldError::new("_id", "is required"));
            }
        }
        Some(_) => {}
    }
    match values.id.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.id.is_some() {
                errors.push(FieldError::new("id", "is required"));
            }
        }
        Some(_) => {}
    }
    match values.name.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.name.is_some() {
                errors.push(FieldError::new("name", "is required"));
            }
        }
        Some(_) => {}
    }
    if errors.is_empty() {
        Ok(())
    } else {
        Err(DomainError::ValidationFailed { entity: "Country".to_string(), errors })
    }
}

/// Values that must be unique are not taken by another row.
async fn check_unique(uow: &dyn UnitOfWork, values: &Values, current: Option<&Country>) -> Result<(), DomainError> {
    {
        let id = values.id.clone().unwrap_or_else(|| current.and_then(|current| current.id));
        if let Some(id) = id {
            if let Some(other) = uow.countries().find_by_id(id).await? {
                if current.is_none_or(|current| other.document_id != current.document_id) {
                    return Err(DomainError::conflict("Country", "id is already taken", &["id"]));
                }
            }
        }
    }
    Ok(())
}

/// Every check before a write: the values, the rows they point to, the unique values.
async fn check_values(uow: &dyn UnitOfWork, values: &Values, current: Option<&Country>) -> Result<(), DomainError> {
    validate(uow, values, current).await?;
    check_unique(uow, values, current).await
}

/// Sets the given values on the entity.
fn apply_values(entity: &mut Country, values: &Values) {
    if let Some(value) = &values.document_id {
        entity.document_id = value.clone();
    }
    if let Some(value) = &values.id {
        entity.id = *value;
    }
    if let Some(value) = &values.name {
        entity.name = value.clone();
    }
}

/// The values an update gives, by field.
fn given(changes: CountryUpdate) -> Values {
    Values { id: Some(Some(changes.id)), name: Some(Some(changes.name)), ..Default::default() }
}

/// The Country with this key; NotFound when there is none.
async fn find(uow: &dyn UnitOfWork, document_id: String) -> Result<Country, DomainError> {
    uow.countries().find_by_document_id(document_id.clone()).await?.ok_or_else(|| DomainError::not_found("Country", document_id))
}

/// The Country as services return it.
fn read(entity: Country) -> CountryRead {
    CountryRead {
        document_id: entity.document_id.expect("document_id is set"),
        id: entity.id.expect("id is set"),
        name: entity.name.expect("name is set"),
    }
}

