    /// Marks a Customer as deleted (deletedAt); reads leave it out from then on.
    pub async fn delete_customer(&self, id: String) -> Result<(), DomainError> {
        let uow = self.unit_of_work.as_ref();
        let mut current = find(uow, id).await?;
        if !uow.orders().list_by_customer(current.id.clone().expect("id is set")).await?.is_empty() {
            return Err(DomainError::conflict("Customer", "rows of orders still point to it", &["orders"]));
        }
        current.deleted_at = Some(chrono::Utc::now());
        uow.customers().update(current).await?;
        Ok(())
    }

    /// The Customer with this email, or None.
    pub async fn find_customer_by_email(&self, email: String) -> Result<Option<CustomerRead>, DomainError> {
        self.unit_of_work.customers().find_by_email(email).await.map(|row| row.map(read))
    }

    /// Adds an item to tags.
    pub async fn add_tag(&self, id: String, tag: String) -> Result<CustomerRead, DomainError> {
        let uow = self.unit_of_work.as_ref();
        find(uow, id.clone()).await?;
        let changed = uow.customers().add_tag(id.clone(), tag).await?.ok_or_else(|| DomainError::not_found("Customer", id))?;
        Ok(read(changed))
    }

    /// Removes an item from tags, by its value.
    pub async fn remove_tag(&self, id: String, tag: String) -> Result<CustomerRead, DomainError> {
        let uow = self.unit_of_work.as_ref();
        let current = find(uow, id.clone()).await?;
        if !(current.tags.as_deref().unwrap_or_default().contains(&tag)) {
            return Err(DomainError::not_found("Tag", tag));
        }
        let changed = uow.customers().remove_tag(id.clone(), tag).await?.ok_or_else(|| DomainError::not_found("Customer", id))?;
        Ok(read(changed))
    }
}

/// The values a create or an update gives, by field: None when not given, Some(None) when given empty.
#[derive(Default)]
struct Values {
    email: Option<Option<String>>,
    name: Option<Option<String>>,
    password_hash: Option<Option<String>>,
    active: Option<Option<bool>>,
    level: Option<Option<String>>,
    address: Option<Option<crate::entities::customer::CustomerAddress>>,
    tags: Option<Option<Vec<String>>>,
    preferences: Option<Option<crate::entities::customer::CustomerPreferences>>,
    extra: Option<Option<mongodb::bson::Bson>>,
    deleted_at: Option<Option<chrono::DateTime<chrono::Utc>>>,
    updated_at: Option<Option<chrono::DateTime<chrono::Utc>>>,
}

/// Checks the values against the rules of the "customers" table, and the rows they point to; ValidationFailed lists every problem.
async fn validate(_uow: &dyn UnitOfWork, values: &Values, current: Option<&Customer>) -> Result<(), DomainError> {
    let creating = current.is_none();
    let mut errors = Vec::new();
    match values.email.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.email.is_some() {
                errors.push(FieldError::new("email", "is required"));
            }
        }
        Some(value) => {
            if value.chars().count() > 120 {
                errors.push(FieldError::new("email", "is longer than 120 characters"));
            }
        }
    }
    match values.name.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.name.is_some() {
                errors.push(FieldError::new("name", "is required"));
            }
        }
        Some(value) => {
            if !(value.as_str().chars().count() >= 2) {
                errors.push(FieldError::new("name", "must have >= 2 characters"));
            }
        }
    }
    if let Some(value) = values.level.as_ref().and_then(|value| value.as_ref()) {
        if !["basic", "gold"].contains(&value.as_str()) {
            errors.push(FieldError::new("level", "must be one of: basic, gold"));
        }
    }
    if let Some(value) = values.address.as_ref().and_then(|value| value.as_ref()) {
        check_customer_address(value, "address", &mut errors);
    }
    if let Some(value) = values.preferences.as_ref().and_then(|value| value.as_ref()) {
        check_customer_preferences(value, "preferences", &mut errors);
    }
    if errors.is_empty() {
        Ok(())
    } else {
        Err(DomainError::ValidationFailed { entity: "Customer".to_string(), errors })
    }
}

/// Values that must be unique are not taken by another row.
async fn check_unique(uow: &dyn UnitOfWork, values: &Values, current: Option<&Customer>) -> Result<(), DomainError> {
    {
        let email = values.email.clone().unwrap_or_else(|| current.and_then(|current| current.email.clone()));
        if let Some(email) = email {
            if let Some(other) = uow.customers().find_by_email(email).await? {
                if current.is_none_or(|current| other.id != current.id) {
                    return Err(DomainError::conflict("Customer", "email is already taken", &["email"]));
                }
            }
        }
    }
    Ok(())
}

/// Every check before a write: the values, the rows they point to, the unique values.
async fn check_values(uow: &dyn UnitOfWork, values: &Values, current: Option<&Customer>) -> Result<(), DomainError> {
    validate(uow, values, current).await?;
    check_unique(uow, values, current).await
}

/// Sets the given values on the entity.
fn apply_values(entity: &mut Customer, values: &Values) {
    if let Some(value) = &values.email {
        entity.email = value.clone();
    }
    if let Some(value) = &values.name {
        entity.name = value.clone();
    }
    if let Some(value) = &values.password_hash {
        entity.password_hash = value.clone();
    }
    if let Some(value) = &values.active {
        entity.active = *value;
    }
    if let Some(value) = &values.level {
        entity.level = value.clone();
    }
    if let Some(value) = &values.address {
        entity.address = value.clone();
    }
    if let Some(value) = &values.tags {
        entity.tags = value.clone();
    }
    if let Some(value) = &values.preferences {
        entity.preferences = value.clone();
    }
    if let Some(value) = &values.extra {
        entity.extra = value.clone();
    }
    if let Some(value) = &values.deleted_at {
        entity.deleted_at = *value;
    }
    if let Some(value) = &values.updated_at {
        entity.updated_at = *value;
    }
}

/// What a CustomerAddress does not follow of its rules, each with the path of its field.
fn check_customer_address(value: &crate::entities::customer::CustomerAddress, path: &str, errors: &mut Vec<FieldError>) {
    if value.street.is_none() {
        errors.push(FieldError::new(&format!("{path}.street"), "is required"));
    }
    if value.city.is_none() {
        errors.push(FieldError::new(&format!("{path}.city"), "is required"));
    }
    if let Some(held) = &value.location {
        check_customer_address_location(held, &format!("{path}.location"), errors);
    }
}

/// What a CustomerAddressLocation does not follow of its rules, each with the path of its field.
fn check_customer_address_location(value: &crate::entities::customer::CustomerAddressLocation, path: &str, errors: &mut Vec<FieldError>) {
    if let Some(held) = &value.r#type {
        if !["Point"].contains(&held.as_str()) {
            errors.push(FieldError::new(&format!("{path}.type"), "must be one of: Point"));
        }
    }
}

/// What a CustomerPreferences does not follow of its rules, each with the path of its field.
fn check_customer_preferences(_value: &crate::entities::customer::CustomerPreferences, _path: &str, _errors: &mut Vec<FieldError>) {
}

/// The values an update gives, by field.
fn given(changes: CustomerUpdate) -> Values {
    Values { email: Some(Some(changes.email)), name: Some(Some(changes.name)), password_hash: Some(changes.password_hash), active: Some(changes.active), level: Some(changes.level), address: Some(changes.address), tags: Some(changes.tags), preferences: Some(changes.preferences), extra: Some(changes.extra), deleted_at: Some(changes.deleted_at), updated_at: Some(changes.updated_at) }
}

/// The Customer with this key; NotFound when there is none.
async fn find(uow: &dyn UnitOfWork, id: String) -> Result<Customer, DomainError> {
    uow.customers().find_by_id(id.clone()).await?.ok_or_else(|| DomainError::not_found("Customer", id))
}

/// The Customer as services return it.
fn read(entity: Customer) -> CustomerRead {
    CustomerRead {
        id: entity.id.expect("id is set"),
        email: entity.email.expect("email is set"),
        name: entity.name.expect("name is set"),
        active: entity.active,
        level: entity.level,
        address: entity.address,
        tags: entity.tags,
        preferences: entity.preferences,
        extra: entity.extra,
        deleted_at: entity.deleted_at,
        created_at: entity.created_at,
        updated_at: entity.updated_at,
    }
}

