//! The service of the "orders" table.

use crate::dtos::order::{OrderCreate, OrderRead, OrderUpdate};
use crate::entities::order::Order;
use crate::errors::{DomainError, FieldError};
use crate::unit_of_work::UnitOfWork;
use std::sync::Arc;

/// Operations on orders. It never commits: the caller owns the transaction.
pub struct OrderService {
    unit_of_work: Arc<dyn UnitOfWork>,
}

impl OrderService {
    pub fn new(unit_of_work: Arc<dyn UnitOfWork>) -> Self {
        Self { unit_of_work }
    }

    /// Stores a new Order after checking it.
    pub async fn create_order(&self, data: OrderCreate) -> Result<OrderRead, DomainError> {
        let values = Values { number: data.number.map(Some), year: data.year.map(Some), customer: data.customer.map(Some), lines: data.lines.map(Some), notes: data.notes.map(Some) };
        let uow = self.unit_of_work.as_ref();
        check_values(uow, &values, None).await?;
        let mut entity = Order::default();
        apply_values(&mut entity, &values);
        let created = uow.orders().insert(entity).await?;
        Ok(read(created))
    }

    /// The Order with this key; NotFound when there is none.
    pub async fn get_order(&self, id: String) -> Result<OrderRead, DomainError> {
        find(self.unit_of_work.as_ref(), id).await.map(read)
    }

    /// Every Order, by primary key.
    pub async fn list_orders(&self) -> Result<Vec<OrderRead>, DomainError> {
        self.unit_of_work.orders().list().await.map(|rows| rows.into_iter().map(read).collect())
    }

    /// Changes the given values of a Order.
    pub async fn update_order(&self, id: String, changes: OrderUpdate) -> Result<OrderRead, DomainError> {
        let values = given(changes);
        let uow = self.unit_of_work.as_ref();
        let mut current = find(uow, id).await?;
        check_values(uow, &values, Some(&current)).await?;
        apply_values(&mut current, &values);
        let updated = uow.orders().update(current).await?;
        Ok(read(updated))
    }

    /// Deletes a Order.
    pub async fn delete_order(&self, id: String) -> Result<(), DomainError> {
        let uow = self.unit_of_work.as_ref();
        let current = find(uow, id).await?;
        uow.orders().delete(&current).await?;
        Ok(())
    }

    /// The Order with this year and number, or None.
    pub async fn find_order_by_year_and_number(&self, year: f64, number: f64) -> Result<Option<OrderRead>, DomainError> {
        self.unit_of_work.orders().find_by_year_and_number(year, number).await.map(|row| row.map(read))
    }

    /// The orders with this customer.
    pub async fn list_orders_by_customer(&self, customer: String) -> Result<Vec<OrderRead>, DomainError> {
        self.unit_of_work.orders().list_by_customer(customer).await.map(|rows| rows.into_iter().map(read).collect())
    }

    /// Adds an item to lines.
    pub async fn add_line(&self, id: String, line: crate::entities::order::OrderLine) -> Result<OrderRead, DomainError> {
        let mut errors: Vec<FieldError> = Vec::new();
        check_order_line(&line, "lines", &mut errors);
        if !errors.is_empty() {
            return Err(DomainError::ValidationFailed { entity: "Order".to_string(), errors });
        }
        let uow = self.unit_of_work.as_ref();
        find(uow, id.clone()).await?;
        let changed = uow.orders().add_line(id.clone(), line).await?.ok_or_else(|| DomainError::not_found("Order", id))?;
        Ok(read(changed))
    }

    /// Removes an item from lines, by its identifier.
    pub async fn remove_line(&self, id: String, line_id: String) -> Result<OrderRead, DomainError> {
        let uow = self.unit_of_work.as_ref();
        let current = find(uow, id.clone()).await?;
        if !(current.lines.as_deref().unwrap_or_default().iter().any(|item| item.id.as_ref() == Some(&line_id))) {
            return Err(DomainError::not_found("Line", line_id));
        }
        let changed = uow.orders().remove_line(id.clone(), line_id).await?.ok_or_else(|| DomainError::not_found("Order", id))?;
        Ok(read(changed))
    }

    /// Adds an item to notes.
    pub async fn add_note(&self, id: String, note: crate::entities::order::OrderNote) -> Result<OrderRead, DomainError> {
        let mut errors: Vec<FieldError> = Vec::new();
        check_order_note(&note, "notes", &mut errors);
        if !errors.is_empty() {
            return Err(DomainError::ValidationFailed { entity: "Order".to_string(), errors });
        }
        let uow = self.unit_of_work.as_ref();
        find(uow, id.clone()).await?;
        let changed = uow.orders().add_note(id.clone(), note).await?.ok_or_else(|| DomainError::not_found("Order", id))?;
        Ok(read(changed))
    }

    /// Removes an item from notes, by its identifier.
    pub async fn remove_note(&self, id: String, note_id: String) -> Result<OrderRead, DomainError> {
        let uow = self.unit_of_work.as_ref();
        let current = find(uow, id.clone()).await?;
        if !(current.notes.as_deref().unwrap_or_default().iter().any(|item| item.id.as_ref() == Some(&note_id))) {
            return Err(DomainError::not_found("Note", note_id));
        }
        let changed = uow.orders().remove_note(id.clone(), note_id).await?.ok_or_else(|| DomainError::not_found("Order", id))?;
        Ok(read(changed))
    }
}

/// The values a create or an update gives, by field: None when not given, Some(None) when given empty.
#[derive(Default)]
struct Values {
    number: Option<Option<f64>>,
    year: Option<Option<f64>>,
    customer: Option<Option<String>>,
    lines: Option<Option<Vec<crate::entities::order::OrderLine>>>,
    notes: Option<Option<Vec<crate::entities::order::OrderNote>>>,
}

/// Checks the values against the rules of the "orders" table, and the rows they point to; ValidationFailed lists every problem.
async fn validate(uow: &dyn UnitOfWork, values: &Values, current: Option<&Order>) -> Result<(), DomainError> {
    let creating = current.is_none();
    let mut errors = Vec::new();
    match values.number.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.number.is_some() {
                errors.push(FieldError::new("number", "is required"));
            }
        }
        Some(_) => {}
    }
    match values.year.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.year.is_some() {
                errors.push(FieldError::new("year", "is required"));
            }
        }
        Some(_) => {}
    }
    match values.customer.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.customer.is_some() {
                errors.push(FieldError::new("customer", "is required"));
            }
        }
        Some(_) => {}
    }
    match values.lines.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.lines.is_some() {
                errors.push(FieldError::new("lines", "is required"));
            }
        }
        Some(value) => {
            for (i0, item0) in value.iter().enumerate() {
                check_order_line(item0, &format!("lines.{i0}"), &mut errors);
            }
        }
    }
    if let Some(value) = values.notes.as_ref().and_then(|value| value.as_ref()) {
        for (i0, item0) in value.iter().enumerate() {
            check_order_note(item0, &format!("notes.{i0}"), &mut errors);
        }
    }
    {
        let customer = values.customer.clone().unwrap_or_else(|| current.and_then(|current| current.customer.clone()));
        if let Some(customer) = customer {
            if uow.customers().find_by_id(customer).await?.is_none() {
                errors.push(FieldError::new("customer", "no Customer has this key"));
            }
        }
    }
    if errors.is_empty() {
        Ok(())
    } else {
        Err(DomainError::ValidationFailed { entity: "Order".to_string(), errors })
    }
}

/// Values that must be unique are not taken by another row.
async fn check_unique(uow: &dyn UnitOfWork, values: &Values, current: Option<&Order>) -> Result<(), DomainError> {
    {
        let year = values.year.clone().unwrap_or_else(|| current.and_then(|current| current.year));
        let number = values.number.clone().unwrap_or_else(|| current.and_then(|current| current.number));
        if let (Some(year), Some(number)) = (year, number) {
            if let Some(other) = uow.orders().find_by_year_and_number(year, number).await? {
                if current.is_none_or(|current| other.id != current.id) {
                    return Err(DomainError::conflict("Order", "year, number is already taken", &["year", "number"]));
                }
            }
        }
    }
    Ok(())
}

/// Every check before a write: the values, the rows they point to, the unique values.
async fn check_values(uow: &dyn UnitOfWork, values: &Values, current: Option<&Order>) -> Result<(), DomainError> {
    validate(uow, values, current).await?;
    check_unique(uow, values, current).await
}

/// Sets the given values on the entity.
fn apply_values(entity: &mut Order, values: &Values) {
    if let Some(value) = &values.number {
        entity.number = *value;
    }
    if let Some(value) = &values.year {
        entity.year = *value;
    }
    if let Some(value) = &values.customer {
        entity.customer = value.clone();
    }
    if let Some(value) = &values.lines {
        entity.lines = value.clone();
    }
    if let Some(value) = &values.notes {
        entity.notes = value.clone();
    }
}

/// What a OrderLine does not follow of its rules, each with the path of its field.
fn check_order_line(value: &crate::entities::order::OrderLine, path: &str, errors: &mut Vec<FieldError>) {
    if value.product.is_none() {
        errors.push(FieldError::new(&format!("{path}.product"), "is required"));
    }
    if let Some(held) = &value.quantity {
        if !((*held as f64) >= 1.0) {
            errors.push(FieldError::new(&format!("{path}.quantity"), "must be >= 1"));
        }
    } else {
        errors.push(FieldError::new(&format!("{path}.quantity"), "is required"));
    }
    if value.price.is_none() {
        errors.push(FieldError::new(&format!("{path}.price"), "is required"));
    }
    if let Some(held) = &value.status {
        if !["pending", "sent"].contains(&held.as_str()) {
            errors.push(FieldError::new(&format!("{path}.status"), "must be one of: pending, sent"));
        }
    }
}

/// What a OrderNote does not follow of its rules, each with the path of its field.
fn check_order_note(_value: &crate::entities::order::OrderNote, _path: &str, _errors: &mut Vec<FieldError>) {
}

/// The values an update gives, by field.
fn given(changes: OrderUpdate) -> Values {
    Values { number: Some(Some(changes.number)), year: Some(Some(changes.year)), customer: Some(Some(changes.customer)), lines: Some(Some(changes.lines)), notes: Some(changes.notes) }
}

/// The Order with this key; NotFound when there is none.
async fn find(uow: &dyn UnitOfWork, id: String) -> Result<Order, DomainError> {
    uow.orders().find_by_id(id.clone()).await?.ok_or_else(|| DomainError::not_found("Order", id))
}

/// The Order as services return it.
fn read(entity: Order) -> OrderRead {
    OrderRead {
        id: entity.id.expect("id is set"),
        number: entity.number.expect("number is set"),
        year: entity.year.expect("year is set"),
        customer: entity.customer.expect("customer is set"),
        lines: entity.lines.expect("lines is set"),
        notes: entity.notes,
        placed_at: entity.placed_at,
    }
}

