    related: Option<Option<Vec<String>>>,
}

/// Checks the values against the rules of the "products" table, and the rows they point to; ValidationFailed lists every problem.
async fn validate(_uow: &dyn UnitOfWork, values: &Values, current: Option<&Product>) -> Result<(), DomainError> {
    let creating = current.is_none();
    let mut errors = Vec::new();
    match values.sku.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.sku.is_some() {
                errors.push(FieldError::new("sku", "is required"));
            }
        }
        Some(_) => {}
    }
    match values.title.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.title.is_some() {
                errors.push(FieldError::new("title", "is required"));
            }
        }
        Some(_) => {}
    }
    match values.price.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.price.is_some() {
                errors.push(FieldError::new("price", "is required"));
            }
        }
        Some(_) => {}
    }
    if let Some(value) = values.stock.as_ref().and_then(|value| value.as_ref()) {
        if !((*value as f64) >= 0.0) {
            errors.push(FieldError::new("stock", "must be >= 0"));
        }
    }
    if errors.is_empty() {
        Ok(())
    } else {
        Err(DomainError::ValidationFailed { entity: "Product".to_string(), errors })
    }
}

/// Values that must be unique are not taken by another row.
async fn check_unique(uow: &dyn UnitOfWork, values: &Values, current: Option<&Product>) -> Result<(), DomainError> {
    {
        let sku = values.sku.clone().unwrap_or_else(|| current.and_then(|current| current.sku.clone()));
        if let Some(sku) = sku {
            if let Some(other) = uow.products().find_by_sku(sku).await? {
                if current.is_none_or(|current| other.id != current.id) {
                    return Err(DomainError::conflict("Product", "sku is already taken", &["sku"]));
                }
            }
        }
    }
    Ok(())
}

/// Every check before a write: the values, the rows they point to, the unique values.
async fn check_values(uow: &dyn UnitOfWork, values: &Values, current: Option<&Product>) -> Result<(), DomainError> {
    validate(uow, values, current).await?;
    check_unique(uow, values, current).await
}

/// Sets the given values on the entity.
fn apply_values(entity: &mut Product, values: &Values) {
    if let Some(value) = &values.sku {
        entity.sku = value.clone();
    }
    if let Some(value) = &values.title {
        entity.title = value.clone();
    }
    if let Some(value) = &values.price {
        entity.price = *value;
    }
    if let Some(value) = &values.stock {
        entity.stock = *value;
    }
    if let Some(value) = &values.reference {
        entity.reference = *value;
    }
    if let Some(value) = &values.picture {
        entity.picture = value.clone();
    }
    if let Some(value) = &values.related {
        entity.related = value.clone();
    }
}

/// The values an update gives, by field.
fn given(changes: ProductUpdate) -> Values {
    Values { sku: Some(Some(changes.sku)), title: Some(Some(changes.title)), price: Some(Some(changes.price)), stock: Some(changes.stock), reference: Some(changes.reference), picture: Some(changes.picture), related: Some(changes.related) }
}

/// The Product with this key; NotFound when there is none.
async fn find(uow: &dyn UnitOfWork, id: String) -> Result<Product, DomainError> {
    uow.products().find_by_id(id.clone()).await?.ok_or_else(|| DomainError::not_found("Product", id))
}

/// The Product as services return it.
fn read(entity: Product) -> ProductRead {
    ProductRead {
        id: entity.id.expect("id is set"),
        sku: entity.sku.expect("sku is set"),
        title: entity.title.expect("title is set"),
        price: entity.price.expect("price is set"),
        stock: entity.stock,
        reference: entity.reference,
        picture: entity.picture,
        related: entity.related,
    }
}

